import {mainDestinations,learningGroups,groupForLesson,lessonById,adjacentLessons,routeContext,contextualLinks,hasAnalyticalWork,searchNavigation} from './navigation.js';
import {observationExplorer,routeIllustration,stageGlyph,methodThread,caseStage} from './atlas.js';
import {createWorksheetCompanion} from './worksheet-companion.js';
import {fieldId,exampleKeyForField} from './work-preview.js';
import {stages,lessons,checklist,redTeam,briefFields,categories,directions,examples,prioritisationDefinitions} from './content.js';
import {blankSession,newTrend,emptyBrief,validateSession,loadSession,saveSession,worksheetSections,exportMarkdown,levels,STORAGE_KEY} from './session.js';

const $=(s,root=document)=>root.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storage; try{storage=window.localStorage;}catch{storage={getItem(){throw Error();},setItem(){throw Error();}};}
const loaded=loadSession(storage);
let session=loaded.session, saveAvailable=loaded.available, source=null, sourceError=false, promptIndex=0, activeFacilitator=0, confirmAction=null;
let timer={seconds:600,running:false,end:0}, toastTimeout, selectedTrend='', observationIndex=0;
const main=$('#main');
let pendingEdit=null;
const companion=createWorksheetCompanion({getSession:()=>session,editField:(stage,path)=>{
  const href='#tool/'+stage;
  if(location.hash===href)focusWorksheetField(path);
  else {pendingEdit={stage,path};location.hash=href;}
}});
function focusWorksheetField(path){
 const target=[...document.querySelectorAll('.worksheet-editor [data-field]')].find(el=>el.dataset.field===path);
 if(!target)return;
 for(let parent=target.parentElement;parent;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;
 target.focus({preventScroll:true});target.scrollIntoView({block:'center',behavior:'instant'});
}
const openLearningGroups=new Set(['before-you-begin']);
const learningGroupChoices=new Map();
let lastNavigationHash=null;
const sourceReady=fetch('./full-guide.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{source=data;}).catch(()=>{sourceError=true;});
const arrow='<span aria-hidden="true">↗</span>';
function route(){return (location.hash.slice(1)||'home').split('/');}
function routeHref(kind,id){return '#'+kind+(id?'/'+id:'');}
function link(href,label,cls=''){return `<a class="${cls}" href="${href}">${label}</a>`;}
function sourceLink(n){const sections=Array.isArray(n)?n:[n];return sections.map(id=>`<a class="source-link" href="#source/${id}">${sections.length>1?`Full guide: section ${id}`:'Read about this in the full guide'}</a>`).join(' · ');}
function eyebrow(text){return `<p class="eyebrow">${text}</p>`;}
function heading(kicker,title,copy,extra=''){return `<header class="page-heading">${kicker?eyebrow(kicker):''}<h1>${title}</h1>${copy?`<p class="lede">${copy}</p>`:''}${extra}</header>`;}
function stageHeading(id,kicker,title,copy,extra=''){return `<div class="stage-heading">${stageGlyph(id)}${heading(kicker,title,copy,extra)}</div>`;}
function callout(title,text,kind=''){return `<aside class="callout ${kind}"><div><strong>${title}</strong><p>${text}</p></div></aside>`;}
function stageStrip(id,mode='lesson'){return `<nav class="stage-strip" aria-label="Five stages">${stages.map(s=>`<a href="#${mode}/${s.id}" aria-label="Stage ${Number(s.number)}: ${s.title}" title="${s.title}" ${s.id===id?'aria-current="step"':''}><span>${Number(s.number)}</span>${s.short}</a>`).join('')}</nav>`;}
function stageSwitch(id,mode=false){const view=mode===true?'tool':mode===false?'lesson':mode;return `<nav class="mode-switch" aria-label="Stage views">${[['lesson','Lesson'],['example','Worked example'],['tool','Your worksheet']].map(([kind,label])=>`<a href="#${kind}/${id}" ${view===kind?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;}
function field(path,label,value,opts={}){
  const id=fieldId(path);
  const help=opts.hint?`<span class="field-hint" id="${id}-hint">${opts.hint}</span>`:'';
  const attr=`id="${id}" data-field="${path}" ${opts.hint?`aria-describedby="${id}-hint"`:''}`;
  let input;
  if(opts.options) input=`<select ${attr}>${opts.options.map(o=>`<option value="${esc(o)}" ${o===value?'selected':''}>${esc(o||'Not assessed')}</option>`).join('')}</select>`;
  else if(opts.type==='checkbox')return `<label class="checkbox-field"><input type="checkbox" ${attr} ${value?'checked':''}><span>${label}${help}</span></label>`;
  else if(opts.type==='text'||opts.type==='number')input=`<input ${attr} type="${opts.type}" value="${esc(value)}" ${opts.type==='number'?`min="0" max="${opts.max||999}" step="1"`: 'maxlength="100000"'} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''}>`;
  else input=`<textarea ${attr} rows="${opts.rows||3}" maxlength="100000" ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''}>${esc(value)}</textarea>`;
  const [view,stage]=route();
  const example=view==='tool'&&!opts.options&&opts.type!=='number'?`<button type="button" class="field-example" data-companion="example" data-example="${exampleKeyForField(stage,path)}" aria-label="See a fictional example for ${esc(label.replace(/<[^>]*>/g,''))}">See an example</button>`:'';
  return `<div class="field"><div class="field-heading"><label class="field-label" for="${id}">${label}</label>${example}</div>${help}${input}</div>`;
}
function renderBreadcrumb(context){
 const breadcrumb=$('#breadcrumb');
 breadcrumb.hidden=!context.breadcrumbs.length;
 breadcrumb.innerHTML=context.breadcrumbs.length?`<ol>${context.breadcrumbs.map((crumb,i)=>`<li class="${i===context.breadcrumbs.length-1?'crumb-current':i===0?'crumb-root':'crumb-intermediate'}">${crumb.href?link(crumb.href,esc(crumb.label)):`<span aria-current="page" title="${esc(crumb.label)}">${esc(crumb.label)}</span>`}</li>`).join('')}</ol>`:'';
}
function sidebarLearning(context){return `<nav class="context-nav learning-nav" aria-label="Learning contents">${learningGroups.map(group=>`<details data-learning-group="${group.id}" class="nav-group ${context.group?.id===group.id?'current-group':''}" ${openLearningGroups.has(group.id)?'open':''}><summary>${group.label}<span class="nav-chevron" aria-hidden="true">›</span></summary><div class="nav-group-lessons">${group.lessonIds.map(id=>{const lesson=lessonById(id),href='#lesson/'+id;const exact=context.href===href;const trail=context.view==='example'&&context.id===id;return `<a href="${href}" class="context-link ${exact?'current':''} ${trail?'in-trail':''}" ${exact?'aria-current="page"':''}>${esc(lesson.title)}${session.lessonDone.includes(id)?'<span class="lesson-read-marker" aria-label="Explored">✓</span>':''}</a>`;}).join('')}</div></details>`).join('')}</nav>`;}
function sidebarTools(context){return `<nav class="context-nav tool-nav" aria-label="${context.section==='session'?'Working session tools':'Workshop tools'}">${contextualLinks(context.section).map(item=>{const exact=context.href===item.href;const trail=context.view==='print'&&item.href==='#session/downloads';return `<a href="${item.href}" class="context-link ${exact?'current':''} ${trail?'in-trail':''}" ${exact?'aria-current="page"':''}>${item.stage?`<span class="nav-stage-number">${item.stage}</span>`:''}<span>${item.label}</span></a>`;}).join('')}</nav>`;}
function renderSidebar(context=routeContext(location.hash,source?.sections)){
 $('#sidebar').innerHTML=`<a href="#home" class="brand" aria-label="Anticipatory analysis home"><img src="./icon.svg" width="37" height="37" alt=""><span>Anticipatory<br>analysis</span></a><p class="side-edition">Interactive guide & facilitation</p><nav class="nav-primary" aria-label="Main sections">${mainDestinations.map(item=>{const active=context.section===item.id;const localExact=contextualLinks(item.id).some(child=>child.href===context.href);return `<div class="nav-section"><a href="${item.href}" class="nav-item ${active?'active':''}" ${context.href===item.href&&!localExact?'aria-current="page"':''}>${item.label}</a>${active&&item.id==='method'?sidebarLearning(context):active&&['session','facilitate'].includes(item.id)?sidebarTools(context):''}</div>`;}).join('')}</nav><div class="sidebar-bottom"><div class="reading-status"><span id="reading-count">${session.lessonDone.length} of ${lessons.length} lessons explored</span><div class="progress-track"><span id="reading-bar" style="width:${session.lessonDone.length/lessons.length*100}%"></span></div></div><a class="full-guide-link ${context.view==='source'?'in-trail':''}" href="#source" ${context.href==='#source'?'aria-current="page"':''}>Read the full guide <span aria-hidden="true">↗</span></a></div>`;
}
$('#sidebar').addEventListener('toggle',e=>{const group=e.target.dataset?.learningGroup;if(!group||!e.target.isConnected||e.target.open===openLearningGroups.has(group))return;learningGroupChoices.set(group,e.target.open);if(e.target.open)openLearningGroups.add(group);else openLearningGroups.delete(group);},true);
function save(){saveAvailable=saveSession(storage,session); updateSaveStatus(); updateProgress();}
function updateSaveStatus(){
  $('#save-status').textContent=saveAvailable?'Saved on this device':'Download to keep your work';
  $('#save-status').classList.toggle('warning',!saveAvailable);
  $('#save-status').title=saveAvailable?'Your working session is saved in this browser. It does not sync across devices.':'Browser saving is unavailable. Download a backup before leaving.';
  const notice=$('#storage-notice');
  if(notice)notice.hidden=saveAvailable;
}
function updateProgress(){if($('#reading-count'))$('#reading-count').textContent=`${session.lessonDone.length} of ${lessons.length} lessons explored`;if($('#reading-bar'))$('#reading-bar').style.width=session.lessonDone.length/lessons.length*100+'%';}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),4800);}
function confirm(title,copy,label,action){$('#confirm-title').textContent=title;$('#confirm-copy').textContent=copy;$('#confirm-accept').textContent=label;confirmAction=action;$('#confirm-dialog').showModal();$('#confirm-cancel').focus();}
function renderHome(){
 const continuing=hasAnalyticalWork(session);
 return `<section class="app-introduction"><h1>An interactive guide to anticipatory analysis</h1><p class="lede">Learn the method, develop your analysis, and facilitate a workshop. Connect evidence and uncertainty to the decisions ahead.</p><a class="home-start-link" href="#lesson/purpose"><span>Start here</span> Define the decision and audience <span aria-hidden="true">↗</span></a></section>
 <nav class="task-launchpad" aria-label="Choose how to use the app">
   <a href="#method" class="launch-link">${routeIllustration('guide')}<div class="launch-heading"><h2>Learn the method</h2><span class="launch-action">Understand the five stages</span></div><p>Begin with purpose and audience, follow the five stages of trend analysis, then explore facilitation and communication tips.</p><span class="launch-arrow" aria-hidden="true">↗</span></a>
   <a href="#session" class="launch-link">${routeIllustration('briefing')}<div class="launch-heading"><h2>Your working session</h2><span class="launch-action">Build your first briefing</span>${continuing?'<span class="launch-resume">Continue your working session</span>':''}</div><p>Frame a question, collect trends, test your reasoning and build a briefing. Keep your notes together as you work.</p><span class="launch-arrow" aria-hidden="true">↗</span></a>
   <a href="#facilitate" class="launch-link">${routeIllustration('workshop')}<div class="launch-heading"><h2>Facilitate a workshop</h2><span class="launch-action">Bring a group together</span></div><p>Adapt the agenda for your group, bring the instructions into the room and guide the discussion with a timer.</p><span class="launch-arrow" aria-hidden="true">↗</span></a>
 </nav>
 <section class="journey-section home-method-preview"><div class="section-heading"><div><h2>One connected process</h2><p class="muted">Move between the lesson and your worksheet at each stage.</p></div>${link('#method/five-stages','See how the stages fit together','text-link')}</div><div class="journey">${stages.map(stage=>`<a class="journey-step" href="#lesson/${stage.id}">${stageGlyph(stage.id)}<span class="step-number">Stage ${Number(stage.number)}</span><h3>${stage.short}</h3><p>${stage.description}</p></a>`).join('')}</div></section>`;
}
function renderMethod(){return heading('Learn at your own pace','Learn the method','Start with purpose and audience, follow the five stages of trend analysis, then explore ideas to help with facilitation and communication. Select any lesson below to explore it, or read them in order.')+`<div class="learning-intro-actions">${link('#lesson/purpose','Define the decision and audience','button primary')}<span>${session.lessonDone.length} of ${lessons.length} lessons explored</span></div><nav class="learning-jump-links" aria-label="Learning groups">${learningGroups.map(group=>link(group.href,group.label)).join('')}</nav><div class="learning-overview">${learningGroups.map(group=>`<section id="${group.anchor}" class="learning-index-group" tabindex="-1"><header><h2>${group.label}</h2><p>${group.description}</p>${group.id==='five-stages'?methodThread():''}${group.id==='communicate-and-continue'?link('#communicate','Open the communication overview','text-link'):''}</header><div class="lesson-index-list">${group.lessonIds.map(id=>{const lesson=lessonById(id),stage=stages.find(item=>item.id===id);return `<article class="lesson-index-row"><a href="#lesson/${id}" class="lesson-index-main"><h3>${esc(lesson.title)}</h3><p>${esc(lesson.deck)}</p>${session.lessonDone.includes(id)?'<span class="lesson-index-status">✓ Explored</span>':''}<span class="lesson-index-action text-link">Explore lesson</span></a>${stage?`<div class="lesson-index-tools"><a class="text-link" href="#tool/${id}" aria-label="Your worksheet: ${esc(lesson.title)}">Your worksheet</a><a class="text-link" href="#example/${id}" aria-label="Worked example: ${esc(lesson.title)}">Worked example</a></div>`:''}</article>`;}).join('')}</div>${group.id==='five-stages'?`<aside class="optional-example"><div><h3>Prefer to follow a worked example?</h3><p>Trace one fictional case through all five stages, from an observation to a revised briefing.</p></div>${link('#example/scan','Explore the example','text-link')}</aside>`:''}</section>`).join('')}</div>`;}
function renderLesson(id){
 const l=lessons.find(x=>x.id===id);if(!l)return notFound();const stage=stages.find(s=>s.id===id);const done=session.lessonDone.includes(id);
 return `${stage?stageHeading(id,'',l.title,l.deck,sourceLink(l.source)):heading('',l.title,l.deck,sourceLink(l.source))}${stage?`<div class="stage-toolbar">${stageStrip(id)}${stageSwitch(id,false)}</div>`:''}<div class="lesson-layout"><article class="lesson-body"><section><h2>Why this matters</h2><p class="large-copy">${l.why}</p></section>${l.definitions?`<section><h2>Assess two dimensions</h2>${l.definitions.map(([label,definition])=>`<p><strong>${label}:</strong> ${definition}</p>`).join('')}</section>`:''}<section><h2>What to do</h2><ol class="instruction-list">${l.actions.map(a=>`<li>${a}</li>`).join('')}</ol></section><div class="output-box">${eyebrow('Your output')}<p>${l.output}</p></div><section class="deeper"><h2>Dig deeper</h2>${l.deeper.map(([title,copy])=>`<details><summary>${title}<span aria-hidden="true">+</span></summary><p>${copy}</p></details>`).join('')}</section><div class="lesson-complete"><button class="button ${done?'outline':'primary'}" data-action="toggle-read" data-id="${id}" aria-pressed="${done}">${done?'✓ Lesson explored':'Mark as explored'}</button><span>Keep track at your own pace.</span></div></article><aside class="lesson-aside"><div class="tip-card">${eyebrow('For the facilitator')}<p>${l.tip}</p></div>${stage?`<a class="example-mini" href="#example/${id}">${stageGlyph(id)}<h3>Explore an example</h3><p>Examine the evidence and the judgement behind the fictional example.</p></a>${link('#tool/'+id,'Open your worksheet','button primary full-width')}`:link('#session','Open your working session','button primary full-width')}</aside></div>${lessonNext(id)}`;
}
function lessonNext(id){const currentGroup=groupForLesson(id);const {previous,next}=adjacentLessons(id);const item=(lesson,direction)=>`<a href="#lesson/${lesson.id}"><span class="lesson-nav-direction">${direction}</span><strong>${esc(lesson.title)}</strong>${groupForLesson(lesson.id).id!==currentGroup.id?`<span class="lesson-nav-group">${groupForLesson(lesson.id).label}</span>`:''}</a>`;return `<nav class="lesson-navigation reading-navigation" aria-label="Lesson navigation">${previous?item(previous,'Previous lesson'):link('#method','All lessons')}${next?item(next,'Next lesson'):link('#checklist','Open the final checklist')}</nav>`;}
function renderExample(id){const e=examples[id];if(!e)return notFound();const stage=stages.find(s=>s.id===id);return `${stageHeading(id,'',e.title,e.body)}<div class="stage-toolbar">${stageStrip(id,'example')}${stageSwitch(id,'example')}</div><p class="fiction-label"><strong>Fictional learning case.</strong> Luma, its sources and all assessments are invented. They stay separate from your working session.</p>${caseStage(id,observationIndex)}<details class="case-notes"><summary>Read the complete notes for this stage</summary><div class="case-notes-body">${e.points.map(([label,text])=>`<section class="example-point"><h2>${label}</h2><p>${text}</p></section>`).join('')}</div></details>${exampleNext(id)}`;}
function exampleNext(id){const i=stages.findIndex(s=>s.id===id);return `<nav class="lesson-navigation" aria-label="Example navigation">${i>0?link('#example/'+stages[i-1].id,'← '+stages[i-1].short):'<span></span>'}${i<4?link('#example/'+stages[i+1].id,'Next: '+stages[i+1].short+' →'):link('#session','Start your own session →')}</nav>`;}
function notFound(){return heading('Page not found','Let’s find your place.','That lesson or worksheet does not exist.')+link('#home','Return to the start →','button primary');}

function sessionActions(){return `<div class="session-actions"><button class="button quiet small" data-action="backup">↓ Download backup</button><button class="button quiet small" data-action="restore">↑ Restore backup</button><button class="button quiet small" data-action="export">Export Markdown</button><button class="button quiet small" data-action="print">Print worksheets</button><input type="file" id="restore-file" accept=".json,application/json" hidden></div>`;}
function storageNotice(){return `<div id="storage-notice" class="storage-notice" ${saveAvailable?'hidden':''}>Browser saving is unavailable. Your work remains usable in this tab; <button class="inline-button" data-action="backup">download a backup</button> before leaving.</div>`;}
function contextForm(){return `<div class="form-grid">${field('context.question','Your analytical question',session.context.question,{rows:3,placeholder:'What could change, for whom, and over what period?',hint:'Keep the question connected to a decision.'})}${field('context.audience','Who is this for?',session.context.audience,{rows:3,placeholder:'Roles, teams or organisations who will use the analysis'})}${field('context.decisions','Decisions or preparedness this could inform',session.context.decisions,{rows:3,placeholder:'What might the audience need to decide, test or prepare?'})}<div>${field('context.geography','Geographic focus',session.context.geography,{type:'text',placeholder:'Place, region or wider system'})}${field('context.horizon','Time horizon',session.context.horizon,{type:'text',placeholder:'For example: the next 6 months; then 6–12 months'})}</div></div>`;}
function renderSession(){return heading('Your working session','Begin with a useful question.','Frame the question, work through the stages and take your notes with you. This is one personal session, saved in this browser.')+storageNotice()+`<section class="worksheet" id="session-brief"><div class="section-heading"><h2>Begin with the brief</h2>${sourceLink(2)}</div>${contextForm()}</section><div class="session-stage-list">${stages.map(s=>`<a href="#tool/${s.id}"><span class="step-number">${s.number}</span><div><h3>${s.title}</h3><p>${s.description}</p></div><span class="tool-count">${s.id==='scan'?session.trends.length+' trends':s.id==='narrative'?session.trends.filter(t=>t.shortlist).length+' shortlisted':s.id==='review'?session.review.checks.filter(Boolean).length+'/12 reviewed':'Open worksheet'} →</span></a>`).join('')}</div><div class="session-review-link">${link('#checklist','Open the final checklist','text-link')}<p>Review the briefing before you share it.</p></div><section class="download-panel" id="session-downloads" tabindex="-1"><h2>Save and download</h2><p>Backups restore your entire working session. Markdown and print give you a readable copy of your notes and briefing. Work does not sync across browsers or devices.</p>${sessionActions()}<button class="text-button danger-text" data-action="clear">Clear this working session</button></section>`;}
function toolHeader(id){const s=stages.find(x=>x.id===id);return stageHeading(id,`Your working session / Stage ${Number(s.number)}`,s.title,s.output)+`<div class="stage-toolbar">${stageStrip(id,'tool')}${stageSwitch(id,true)}</div>`+storageNotice()+`<div class="session-context"><span><strong>Question</strong> ${esc(session.context.question||'Set the question your analysis will explore.')}</span>${link('#session','Edit brief')}</div>`;}
function toolFooter(id){const i=stages.findIndex(s=>s.id===id);return `<nav class="lesson-navigation" aria-label="Worksheet navigation">${i>0?link('#tool/'+stages[i-1].id,'← '+stages[i-1].title):link('#session','← Session brief')}${i<4?link('#tool/'+stages[i+1].id,stages[i+1].title+' →'):link('#session','Download your work →')}</nav>`;}
function trendTitle(t,i){return t.title.trim()||`Untitled trend ${i+1}`;}
function noTrends(message='Start by recording a trend in the scanning worksheet.'){return `<div class="empty-state"><span aria-hidden="true">↗</span><h2>Give your analysis a starting point.</h2><p>${message}</p>${link('#tool/scan','Add your first trend →','button primary')}</div>`;}
function renderScan(){return `<div class="section-heading"><div><h2>Your emerging trends</h2><p class="muted">Describe a pattern of change, then examine its outlook.</p></div>${session.trends.length?'<button class="button primary" data-action="add-trend">+ Add a trend</button>':''}</div>${!session.trends.length?`<div class="empty-state"><h2>What is changing?</h2><p>Start with one emerging pattern. Record what supports it and what you do not yet know.</p><button class="button primary" data-action="add-trend">+ Create your first trend</button>${link('#example/scan','See a fictional example','text-link')}</div>`:''}<div class="trend-list">${session.trends.map((t,i)=>`<details class="trend-editor" id="trend-${t.id}" ${selectedTrend===t.id||(!selectedTrend&&i===0)?'open':''}><summary><span class="trend-index">${String(i+1).padStart(2,'0')}</span><span id="trend-title-${t.id}">${esc(trendTitle(t,i))}</span><span class="tag">${t.category}</span><span aria-hidden="true">+</span></summary><div class="trend-fields">${field(`trend.${t.id}.title`,'Trend',t.title,{type:'text',placeholder:'A sustained or emerging pattern of change'})}<div class="form-grid">${field(`trend.${t.id}.category`,'STEEP category',t.category,{options:categories})}${field(`trend.${t.id}.direction`,'Direction',t.direction,{options:directions})}</div>${field(`trend.${t.id}.evidence`,'Evidence and source dates',t.evidence,{rows:4,placeholder:'Observable data, documented developments, credible reporting or expert assessments. Record the source and date.',hint:'Separate what has been observed from your judgement about the future.'})}<div class="form-grid">${field(`trend.${t.id}.uncertainty`,'Uncertainty',t.uncertainty,{rows:4,placeholder:'What is unknown, contested, weakly evidenced or conditional?'})}${field(`trend.${t.id}.outlook`,'Outlook',t.outlook,{rows:4,placeholder:'What might sustain, accelerate, disrupt or reverse the trend? Through what mechanisms could consequences follow?'})}</div><button class="text-button danger-text" data-action="delete-trend" data-id="${t.id}">Remove this trend</button></div></details>`).join('')}</div>${callout('Think beyond the description','Consider scheduled events, underlying drivers, possible disruptions and known unknowns. Explain why a change could matter within your chosen time horizon.')}`;}
function renderPrioritise(){if(!session.trends.length)return noTrends();return callout('Agree what you are judging','The trend may already be happening. Define the future proposition and time horizon before choosing likelihood. This matrix and the vote help to structure your discussion; they do not produce an objective risk score.')+`<div class="trend-list">${session.trends.map((t,i)=>`<details class="trend-editor" id="trend-${t.id}" ${i===0?'open':''}><summary><span class="trend-index">${String(i+1).padStart(2,'0')}</span><span>${esc(trendTitle(t,i))}</span><span aria-hidden="true">+</span></summary><div class="trend-fields">${field(`trend.${t.id}.proposition`,'What future proposition are you assessing?',t.proposition,{placeholder:'Specify the change or consequence, and the period being considered.'})}<div class="form-grid three">${field(`trend.${t.id}.likelihood`,'Likelihood',t.likelihood,{options:['',...levels],hint:prioritisationDefinitions.likelihood})}${field(`trend.${t.id}.impact`,'Humanitarian impact',t.impact,{options:['',...levels],hint:prioritisationDefinitions.impact})}${field(`trend.${t.id}.votes`,'Workshop dot-votes',t.votes,{type:'number',hint:'Enter the group’s tally manually.'})}</div>${field(`trend.${t.id}.rationale`,'Reasoning and affected people',t.rationale,{placeholder:'Explain your judgement. Consider scale, severity, affected groups and response capacity.'})}${field(`trend.${t.id}.watch`,'Keep on the watch list',t.watch,{type:'checkbox',hint:'Retain important possibilities that may need monitoring or contingency planning.'})}</div></details>`).join('')}</div>`;}
function renderNarrative(){return `${session.trends.length?`<section class="worksheet"><div class="section-heading"><h2>Agree the shortlist</h2><button type="button" class="field-example" data-companion="example" data-example="4">See an example</button><span id="shortlist-count" class="tag">${session.trends.filter(t=>t.shortlist).length} selected</span></div><p class="muted">Use the vote as an input. Combine or drop overlapping trends and check what the group may have missed.</p><div class="shortlist-options">${session.trends.map((t,i)=>field(`trend.${t.id}.shortlist`,`${esc(trendTitle(t,i))}<small>${t.votes} vote${t.votes===1?'':'s'} · ${esc(t.category)}${t.watch?' · Watch list':''}</small>`,t.shortlist,{type:'checkbox'})).join('')}</div></section>`:noTrends()}<section class="worksheet"><h2>Find the connections</h2>${field('narrative.relationships','Relationships, overlaps and missing perspectives',session.narrative.relationships,{rows:4,placeholder:'Common drivers? Similar consequences? Amplifying or counteracting effects? Whose perspective is missing?'})}${field('narrative.story','The overarching story',session.narrative.story,{rows:4,placeholder:'How are humanitarian risks changing, and what connects the shortlisted trends?'})}</section><section class="worksheet"><h2>Sketch a causal pathway</h2><p class="muted">Use a simple chain to test your reasoning. The arrows describe a proposed relationship, not proof of causality.</p><div class="form-grid three">${field('narrative.driver','Driver',session.narrative.driver,{rows:3})}${field('narrative.trend','Trend',session.narrative.trend,{rows:3})}${field('narrative.consequence','Possible humanitarian consequence',session.narrative.consequence,{rows:3})}</div><h3 class="assumptions-heading">What does each connection depend on?</h3><div class="form-grid">${field('narrative.driverAssumption','Between driver and trend',session.narrative.driverAssumption,{rows:3,placeholder:'What must hold for the driver to produce this change?'})}${field('narrative.consequenceAssumption','Between trend and consequence',session.narrative.consequenceAssumption,{rows:3,placeholder:'What could interrupt or offset the consequence?'})}</div>${field('narrative.alternative','Another interpretation of the evidence',session.narrative.alternative,{rows:3,placeholder:'What else could explain the pattern? What would help you distinguish the explanations?'})}</section>`;}
const briefHints={summary:'What is changing, and what is the outlook over your time horizon?',consequences:'What could happen, to whom, where, when and through what causal pathways? Consider needs, vulnerability, access and response capacity.',actors:'Who drives or influences the trend, and who is likely to be affected?',evidence:'Which sources support the analysis? How strong, recent and relevant are they?',uncertainties:'What could make this outlook wrong? What alternative interpretations or trajectories deserve consideration?',indicators:'What observable developments would strengthen, weaken or materially change the assessment?',considerations:'Questions for operations, preparedness, policy or diplomacy audiences. Develop recommendations with those expected to implement them.'};
function briefingEditor(t){const b=session.briefing.trends[t.id]||emptyBrief();return `<details class="trend-editor" ${t.shortlist?'open':''}><summary><span>${esc(trendTitle(t,session.trends.indexOf(t)))}</span>${!t.shortlist?'<span class="tag">Retained draft · not shortlisted</span>':''}<span aria-hidden="true">+</span></summary><div class="trend-fields">${briefFields.map(([key,label],i)=>field(`brief.${t.id}.${key}`,`${i<6?String(i+1).padStart(2,'0')+' · ':''}${label}`,b[key],{rows:key==='consequences'?4:3,hint:briefHints[key]})).join('')}</div></details>`;}
function renderWrite(){const shortlisted=session.trends.filter(t=>t.shortlist);const retained=session.trends.filter(t=>!t.shortlist&&session.briefing.trends[t.id]);return callout('Speak or write with one consistent voice','Give each shortlisted trend a group and appoint a smaller team to draft the opening, conclusion and overarching narrative. Keep findings, implications, considerations and recommendations distinct.')+`<section class="worksheet"><h2>Open with what is at stake</h2>${field('briefing.intro','Introduction',session.briefing.intro,{rows:4,placeholder:'What is at stake? Why should this audience care now? Set out the question and time horizon.'})}</section>${shortlisted.length?`<h2 class="subsection-heading">Your shortlisted trends</h2>${shortlisted.map(briefingEditor).join('')}`:`<div class="empty-state"><h2>Choose the trends that belong in the story.</h2><p>Select a shortlist in stage three to open a structured briefing for each trend.</p>${link('#tool/narrative','Agree your shortlist →','button primary')}</div>`}${retained.length?`<h2 class="subsection-heading">Previously drafted trends</h2><p class="muted">These drafts are retained even though the trends are not currently shortlisted.</p>${retained.map(briefingEditor).join('')}`:''}<section class="worksheet"><h2>Close with the implications</h2>${field('briefing.conclusion','Conclusion',session.briefing.conclusion,{rows:4,placeholder:'Bring together the implications, important uncertainties and what to monitor. Avoid simply repeating the summaries.'})}</section>`;}
function redTeamCard(){const [title,q,hint]=redTeam[promptIndex];return `<div class="red-team-card">${eyebrow('Red-teaming')}<div class="red-team-count">${String(promptIndex+1).padStart(2,'0')} / 08</div><h2>${title}</h2><p class="red-team-question">${q}</p><p>${hint}</p><div class="button-row"><button class="icon-button" data-action="previous-prompt" aria-label="Previous red-team prompt">←</button><div class="prompt-dots">${redTeam.map((_,i)=>`<button data-action="select-prompt" data-index="${i}" aria-label="Red-team prompt ${i+1}: ${esc(redTeam[i][0])}" ${i===promptIndex?'aria-current="true"':''}></button>`).join('')}</div><button class="icon-button" data-action="next-prompt" aria-label="Next red-team prompt">→</button></div></div>`;}
function checklistForm(){return `<div class="checklist-progress"><div><strong id="check-count">${session.review.checks.filter(Boolean).length}</strong><span> of 12 reviewed</span></div><p>Completion is not a quality score.</p></div><div class="checklist-grid">${checklist.map(([title,q],i)=>`<label class="check-item ${session.review.checks[i]?'checked':''}"><input type="checkbox" id="${fieldId(`review.checks.${i}`)}" data-field="review.checks.${i}" ${session.review.checks[i]?'checked':''}><span><span class="check-item-title"><small>${String(i+1).padStart(2,'0')}</small>${title}</span><span>${q}</span></span></label>`).join('')}</div>`;}
function renderReview(){return `<div id="red-team-view">${redTeamCard()}</div><section class="worksheet">${field('review.notes','Revision notes and unresolved questions',session.review.notes,{rows:5,placeholder:'What changed after challenge? What remains uncertain? Who will follow up?'})}</section><section><div class="section-heading"><h2>Before you share the briefing</h2><button type="button" class="field-example" data-companion="example" data-example="0">See an example</button>${sourceLink(7)}</div>${checklistForm()}</section>`;}
function renderTool(id){if(!stages.some(s=>s.id===id))return notFound();const renderers={scan:renderScan,prioritise:renderPrioritise,narrative:renderNarrative,write:renderWrite,review:renderReview};return toolHeader(id)+companion.wrap(renderers[id]())+toolFooter(id);}

function lessonTiles(ids){return `<div class="lesson-tiles">${ids.map(id=>{const l=lessons.find(x=>x.id===id);return `<a href="#lesson/${id}"><h2>${l.title}</h2><p>${l.deck}</p><span class="text-link">Explore lesson</span></a>`;}).join('')}</div>`;}
function renderFacilitate(){return heading('Plan, then bring the process into the room','Facilitate a workshop','Set the shared question, adapt the agenda and open the facilitator view when your group is ready.')+`<div class="button-row heading-actions">${link('#present','Open facilitator view','button primary')}${link('#session','Set the shared question','button quiet')}${link('#facilitate/agenda','Edit the agenda','text-link')}</div><section class="worksheet" id="workshop-agenda" tabindex="-1"><div class="section-heading"><div><h2>Outline of the analytical sprint</h2></div><span class="agenda-total" id="agenda-total">${session.agenda.reduce((n,a)=>n+a.minutes,0)} min total</span></div><p class="muted">Timings are illustrative, not prescribed. Edit the agenda, and move or split breaks as the group needs.</p><div class="agenda-list">${session.agenda.map((a,i)=>`<div class="agenda-row"><span>${String(i+1).padStart(2,'0')}</span>${field(`agenda.${i}.title`,`Agenda item ${i+1}`,a.title,{type:'text'})}${field(`agenda.${i}.minutes`,'Minutes',a.minutes,{type:'number',max:1440})}</div>`).join('')}</div></section><section class="facilitation-reading"><div class="section-heading"><div><h2>Facilitation tips</h2><p class="muted">Select a lesson below to explore tips for designing and facilitating an analytical workshop.</p></div>${link('#method/facilitation','All facilitation lessons','text-link')}</div>${lessonTiles(['collaboration','ai','care'])}</section>${callout('Make the transitions explicit','At each stage, explain why it matters, what participants should do, what they should produce and how that output will support the next stage. Build in opportunities to pause and step away.')}`;}
function facilitatorContent(){const entry=session.agenda[activeFacilitator];const stage=stages[activeFacilitator-1];const instructions=activeFacilitator===0?['State the analytical question, audience, decisions and time horizon.','Introduce the five-stage process, expected briefing and roles.','Agree how the group will work together, including pauses and opportunities to step away.']:activeFacilitator===6?['Pause the analytical work.','Give people time to step away, reflect or check in.','Agree when to return and which stage comes next.']:stage.instructions;const output=activeFacilitator===0?'A shared purpose, clear roles and an agreed way of working.':activeFacilitator===6?'A group ready to continue at an appropriate pace.':stage.output;return `<div class="facilitator-top"><a class="text-link" href="#facilitate">← Back to workshop planning</a><button class="button quiet small" data-action="fullscreen">Expand view ↗</button></div>${heading('Facilitator view · '+(activeFacilitator===0?'Set the scene':activeFacilitator===6?'Make room to pause':`Stage ${stage.number}`),esc(entry.title),esc(session.context.question||'Set a shared analytical question in your working session.'))}<div class="facilitator-layout"><div><ol class="instruction-list large-instructions">${instructions.map(x=>`<li>${x}</li>`).join('')}</ol><div class="output-box">${eyebrow('Leave with')}<p>${output}</p></div></div><aside class="timer-card">${eyebrow('Time for this stage')}<div class="timer-display" id="timer-display" role="timer" aria-live="off">${formatTime(timer.seconds)}</div><p id="timer-state">${timer.running?'Running':timer.seconds===0?'Time is up':'Ready when you are'}</p><div class="button-row"><button class="button primary" data-action="timer-toggle" id="timer-toggle">${timer.running?'Pause':'Start timer'}</button><button class="button quiet" data-action="timer-reset">Reset</button></div><p class="caption">Time is a guide. Pause or extend the conversation when needed.</p></aside></div><nav class="facilitator-stages" aria-label="Workshop agenda">${session.agenda.map((a,i)=>`<button data-action="facilitator-stage" data-index="${i}" ${activeFacilitator===i?'aria-current="step"':''}>${esc(a.title)}<small>${a.minutes} min</small></button>`).join('')}</nav>`;}
function renderCommunicate(){return heading('','Communication overview','Help people understand what is changing, why it matters and what observations could change the assessment.')+lessonTiles(['communicate','network','follow-through'])+callout('Prepare the handover','Decide how the briefing will be shared, discussed, challenged and updated. Capture the questions your audience asks: they reveal what is useful and what needs more explanation.')+`<div class="button-row">${link('#tool/write','Return to your briefing →','button primary')}${link('#checklist','Review before sharing','button quiet')}</div>`;}
function renderChecklist(){return heading('Before publishing or presenting','Twelve questions worth asking.','Use this final check to surface gaps, strengthen the briefing and agree what happens next.',sourceLink(7))+storageNotice()+checklistForm()+`<div class="button-row heading-actions">${link('#tool/review','Open red-team prompts →','button primary')}<button class="button quiet" data-action="print">Print your worksheets</button></div>`;}
function printContents(){const context=session.context.question?`<p>${esc(session.context.question)}</p>`:'';return `<h1>Anticipatory analysis working session</h1>${context}<p>Personal worksheets · ${new Date().toLocaleDateString('en-GB')}</p>${worksheetSections(session).map(s=>`<section><h2>${esc(s.title)}</h2><div class="print-text">${esc(s.text)}</div></section>`).join('')}<p>Method adapted from A practical guide to rapid anticipatory humanitarian analysis. User-entered work only; fictional examples excluded.</p>`;}
function renderPrintPreview(){return heading('Your working session · Print preview','Your worksheets','Review your notes below, then use your browser’s print controls to print or save as PDF.')+`<div class="button-row heading-actions"><button class="button primary" data-action="browser-print">Print or save as PDF</button>${link('#session/downloads','Back to save and download','button quiet')}</div><article class="print-preview">${printContents()}</article>`;}
function renderSource(id){if(!source)return heading('','The complete guide.',sourceError?'The guide could not be loaded. Refresh the page to try again.':'Loading the source text…');return heading('','A practical guide to rapid anticipatory humanitarian analysis','This guidance is based on a method developed by Madeleine Lyons and Barbara Devlieger.')+`<nav class="source-toc" aria-label="Source sections">${source.sections.map(s=>link('#source/'+s.id,esc(s.title))).join('')}</nav><div class="source-body">${source.sections.map(s=>`<section id="source-${s.id}" class="source-section"><h2>${esc(s.title)}</h2>${s.html}</section>`).join('')}</div>`;}
async function render({focus=true}={}){
 companion.beforeRender();
 let context=routeContext(location.hash,source?.sections);
 const {view,id}=context;
 if(context.valid&&view==='lesson'&&location.hash!==context.href)history.replaceState(history.state,'',context.href);
 if(context.href!==lastNavigationHash){openLearningGroups.clear();if(!context.group&&!learningGroupChoices.has('before-you-begin'))openLearningGroups.add('before-you-begin');for(const [group,open] of learningGroupChoices)if(open)openLearningGroups.add(group);if(context.group)openLearningGroups.add(context.group.id);lastNavigationHash=context.href;}
 document.body.classList.toggle('presenting',view==='present'&&context.valid);
 document.body.dataset.view=context.valid?view:'not-found';
 document.body.dataset.section=context.section||'';
 document.body.classList.remove('nav-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','Open navigation');
 const renderers={home:renderHome,method:renderMethod,lesson:()=>renderLesson(id),example:()=>renderExample(id),session:renderSession,tool:()=>renderTool(id),facilitate:renderFacilitate,present:facilitatorContent,communicate:renderCommunicate,checklist:renderChecklist,source:()=>renderSource(id),print:renderPrintPreview};
 main.innerHTML=(context.valid&&renderers[view]?renderers[view]:notFound)();
 renderBreadcrumb(context);renderSidebar(context);updateSaveStatus();
 if(view==='tool'&&context.valid)companion.mount(id);
 document.title=`${context.title} · Anticipatory analysis`;
 updateSidebarAccess();
 if(focus){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}
 if(view==='source'&&context.valid&&!source&&!sourceError){await sourceReady;if(routeContext(location.hash).href!==context.href)return;main.innerHTML=renderSource(id);context=routeContext(location.hash,source?.sections);renderBreadcrumb(context);document.title=`${context.title} · Anticipatory analysis`;}
 if(pendingEdit&&view==='tool'&&id===pendingEdit.stage){const target=pendingEdit;pendingEdit=null;focusWorksheetField(target.path);}
 if(context.anchor&&routeContext(location.hash).href===context.href){const target=document.getElementById(context.anchor);if(target){target.setAttribute('tabindex','-1');target.scrollIntoView({block:'start',behavior:'instant'});target.focus({preventScroll:true});}}
}
function getFieldTarget(path){const [group,id,key]=path.split('.');if(group==='trend')return [session.trends.find(t=>t.id===id),key];if(group==='brief'){if(!session.briefing.trends[id])session.briefing.trends[id]=emptyBrief();return [session.briefing.trends[id],key];}if(group==='agenda')return [session.agenda[Number(id)],key];if(group==='review'&&id==='checks')return [session.review.checks,Number(key)];return [session[group],id];}
function handleField(target){if(!target.dataset.field)return;const [obj,key]=getFieldTarget(target.dataset.field);if(!obj)return;let value=target.type==='checkbox'?target.checked:target.value;if(target.type==='number'){if(target.value===''||!target.checkValidity())return;value=Number(target.value);}obj[key]=value;save();companion.refresh();const path=target.dataset.field;
 if(path.startsWith('trend.')){
  const id=path.split('.')[1];
  if(key==='title'&&$('#trend-title-'+id))$('#trend-title-'+id).textContent=value||'Untitled trend';
  if(key==='category'){const tag=target.closest('.trend-editor')?.querySelector('summary .tag');if(tag)tag.textContent=value;}
  if(key==='shortlist'&&$('#shortlist-count'))$('#shortlist-count').textContent=session.trends.filter(t=>t.shortlist).length+' selected';
 }
 if(path.startsWith('review.checks')){target.closest('.check-item')?.classList.toggle('checked',value);if($('#check-count'))$('#check-count').textContent=session.review.checks.filter(Boolean).length;}
 if(path.startsWith('agenda.')){if($('#agenda-total'))$('#agenda-total').textContent=session.agenda.reduce((n,a)=>n+a.minutes,0)+' min total';if(key==='minutes'&&Number(path.split('.')[1])===activeFacilitator)resetTimer();}
}
function download(filename,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function preparePrint(){$('#print-root').innerHTML=printContents();}
function formatTime(seconds){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}
function resetTimer(){timer.running=false;timer.seconds=session.agenda[activeFacilitator].minutes*60;timer.end=0;updateTimer();}
function updateTimer(){if($('#timer-display')){$('#timer-display').textContent=formatTime(timer.seconds);$('#timer-state').textContent=timer.seconds===0?'Time is up':timer.running?'Running':'Paused / ready';$('#timer-toggle').textContent=timer.running?'Pause':'Start timer';}}
setInterval(()=>{if(timer.running){timer.seconds=Math.max(0,Math.ceil((timer.end-Date.now())/1000));if(timer.seconds===0){timer.running=false;toast('Time for this stage is up. Continue or take a pause as needed.');}updateTimer();}},250);

document.addEventListener('input',e=>{if(e.target.matches('[data-field]'))handleField(e.target);});
document.addEventListener('change',async e=>{
 if(e.target.id!=='restore-file')return;
 const file=e.target.files[0];e.target.value='';if(!file)return;
 try{if(file.size>2_000_000)throw Error('The backup is too large (maximum 2 MB).');const imported=validateSession(JSON.parse(await file.text()));confirm('Restore this backup?','This will replace the current working session, including notes, agenda and reading progress. Download a backup first if you want to keep your current work.','Restore backup',()=>{session=imported;selectedTrend='';companion.resetSelection();resetTimer();save();render();toast('Backup restored.');});}catch(error){toast('Could not restore backup: '+error.message);}
});
document.addEventListener('click',async e=>{
 const closer=e.target.closest('[data-close-dialog]');if(closer){$('#'+closer.dataset.closeDialog).close();return;}
 const samePage=e.target.closest('a[href^="#"]');if(samePage&&samePage.hash===location.hash&&routeContext(samePage.hash).valid){e.preventDefault();render();return;}
 const button=e.target.closest('[data-action]');if(!button)return;
 const {action,id,index}=button.dataset;
 if(action==='observe'){observationIndex=Math.max(0,Math.min(2,Number(index)||0));const explorer=$('#case-explorer');const updated=document.createElement('div');updated.innerHTML=observationExplorer(observationIndex);$('.luma-map',explorer).outerHTML=$('.luma-map',updated).outerHTML;$('#observation-reading').innerHTML=$('#observation-reading',updated).innerHTML;explorer.querySelectorAll('[data-action="observe"]').forEach(control=>control.setAttribute('aria-pressed',String(Number(control.dataset.index)===observationIndex)));}
 if(action==='toggle-read'){session.lessonDone=session.lessonDone.includes(id)?session.lessonDone.filter(x=>x!==id):[...session.lessonDone,id];save();const done=session.lessonDone.includes(id);button.textContent=done?'✓ Lesson explored':'Mark as explored';button.setAttribute('aria-pressed',String(done));button.classList.toggle('primary',!done);button.classList.toggle('outline',done);renderSidebar();}
 if(action==='add-trend'){if(session.trends.length>=200){toast('This session supports up to 200 trends. Export your work to begin another session.');return;}const t=newTrend();session.trends.push(t);selectedTrend=t.id;save();render({focus:false});$('#f-trend-'+t.id+'-title').focus();}
 if(action==='delete-trend'){confirm('Remove this trend?','This also removes its prioritisation, shortlist entry and any briefing draft. Other trends and notes are kept.','Remove trend',()=>{session.trends=session.trends.filter(t=>t.id!==id);delete session.briefing.trends[id];save();render();toast('Trend removed.');});}
 if(action==='focus-trend'){const item=$('#trend-'+id);if(item){item.open=true;item.scrollIntoView({block:'start',behavior:'smooth'});$('summary',item).focus();}}
 if(action==='next-prompt'||action==='previous-prompt'||action==='select-prompt'){promptIndex=action==='select-prompt'?Number(index):(promptIndex+(action==='next-prompt'?1:7))%8;$('#red-team-view').innerHTML=redTeamCard();$(`[data-action="${action}"]${action==='select-prompt'?`[data-index="${index}"]`:''}`,$('#red-team-view'))?.focus({preventScroll:true});}
 if(action==='backup'){download('anticipatory-analysis-backup.json',JSON.stringify(session,null,2),'application/json');toast('Backup downloaded. Keep it to restore this session.');}
 if(action==='export'){download('anticipatory-analysis-worksheets.md',exportMarkdown(session),'text/markdown;charset=utf-8');toast('Worksheets exported as Markdown.');}
 if(action==='restore')$('#restore-file').click();
 if(action==='print'){location.hash='print';}
 if(action==='browser-print'){preparePrint();window.print();}
 if(action==='clear'){confirm('Clear this working session?','This clears all notes, trends, drafts, checklist entries and reading progress on this browser. Download a backup first if you need to keep them.','Clear session',()=>{session=blankSession();companion.resetSelection();selectedTrend='', observationIndex=0;activeFacilitator=0;resetTimer();save();render();toast('A fresh working session is ready.');});}
 if(action==='facilitator-stage'){activeFacilitator=Number(index);resetTimer();render({focus:false});$(`[data-action="facilitator-stage"][data-index="${index}"]`)?.focus({preventScroll:true});}
 if(action==='timer-toggle'){if(timer.running){timer.seconds=Math.max(0,Math.ceil((timer.end-Date.now())/1000));timer.running=false;}else{if(timer.seconds===0)timer.seconds=session.agenda[activeFacilitator].minutes*60;timer.running=true;timer.end=Date.now()+timer.seconds*1000;}updateTimer();}
 if(action==='timer-reset')resetTimer();
 if(action==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('The focused facilitator layout is ready. Fullscreen is unavailable in this browser.');}}
});
$('#confirm-cancel').addEventListener('click',()=>{$('#confirm-dialog').close();confirmAction=null;});
$('#confirm-accept').addEventListener('click',()=>{const action=confirmAction;confirmAction=null;$('#confirm-dialog').close();action?.();});
$('#confirm-dialog').addEventListener('cancel',()=>{confirmAction=null;});
function updateSidebarAccess(){const hidden=window.matchMedia('(max-width:780px)').matches&&!document.body.classList.contains('nav-open');$('#sidebar').inert=hidden;}
window.matchMedia('(max-width:780px)').addEventListener('change',updateSidebarAccess);
$('.skip').addEventListener('click',e=>{e.preventDefault();main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});});
$('#menu-toggle').addEventListener('click',()=>{const open=document.body.classList.toggle('nav-open');$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');updateSidebarAccess();if(open){const current=$('#sidebar .context-link[aria-current="page"]')||$('#sidebar .nav-item.active')||$('#sidebar a');current.focus();current.scrollIntoView({block:'nearest'});}});
document.addEventListener('click',e=>{if(document.body.classList.contains('nav-open')&&!e.target.closest('#sidebar,#menu-toggle')){document.body.classList.remove('nav-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','Open navigation');updateSidebarAccess();}});
function searchResults(query){
 const results=searchNavigation(query,source?.sections||[]);
 return `<p class="search-count">${query.trim()?results.length+' result'+(results.length===1?'':'s'):'Common destinations'}</p>${results.length?results.map(result=>`<a href="${result.href}" class="search-result">${result.path!==result.title?`<span class="search-path">${esc(result.path)}</span>`:''}<strong>${esc(result.title)}</strong><p>${esc(result.description)}</p></a>`).join(''):'<div class="empty-search"><h3>No matching pages yet.</h3><p>Try a broader term such as evidence, audience or uncertainty.</p></div>'}`;
}
async function openSearch(){$('#search-dialog').showModal();$('#search-input').value='';$('#search-results').innerHTML=searchResults('');$('#search-input').focus();await sourceReady;if($('#search-dialog').open)$('#search-results').innerHTML=searchResults($('#search-input').value);}
$('#open-search').addEventListener('click',openSearch);
$('#open-about').addEventListener('click',()=>{$('#about-dialog').showModal();});
$('#about-dialog').addEventListener('close',()=>{$('#open-about').focus({preventScroll:true});});
$('#search-input').addEventListener('input',e=>{$('#search-results').innerHTML=searchResults(e.target.value);});
$('#search-results').addEventListener('click',e=>{if(e.target.closest('a')){$('#search-dialog').close();if(e.target.closest('a').hash===location.hash)render();}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.target.matches('input,textarea,select')&&!e.target.isContentEditable&&!document.querySelector('dialog[open]')){e.preventDefault();openSearch();}if(e.key==='Escape'&&document.body.classList.contains('nav-open')){document.body.classList.remove('nav-open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','Open navigation');updateSidebarAccess();$('#menu-toggle').focus();}});
window.addEventListener('hashchange',()=>render());
window.addEventListener('beforeprint',preparePrint);
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY)toast('This session changed in another tab. Download any work here before reloading.');});
resetTimer();render({focus:false});
if(loaded.warning)toast(loaded.warning);
